/// <summary>
/// The <c>METInventOnhandItemValidateUnitFlight</c> class handles the flighting logic to ensure that non existing unit fails validation when selecting other type of unit.
/// </summary>
internal final class METInventOnhandItemValidateUnitFlight extends Flight
{
    static private METInventOnhandItemValidateUnitFlight singleton = new METInventOnhandItemValidateUnitFlight();

}

Method.Source:
/// <summary>
/// isEnabledByDefault method is used to determine whether the flight is enabled by default.
/// </summary>
/// <returns>boolean</returns>
[Hookable(false)]
protected boolean isEnabledByDefault()
{
    return true;
}

/// <summary>
/// singleton method returns the instance of the METInventOnhandItemValidateUnitFlight class.
/// </summary>
/// <returns>METInventOnhandItemValidateUnitFlight</returns>
[Hookable(false)]
public static METInventOnhandItemValidateUnitFlight instance()
{
    return singleton;
}
